#!/bin/sh
# Seed sample mail into each account's INBOX (once) and run Dovecot in the foreground.
set -eu

# Wait for the self-signed certificate generated by the compose "certgen" service.
tries=0
while [ ! -s /certs/tls.crt ] || [ ! -s /certs/tls.key ]; do
    tries=$((tries + 1))
    if [ "$tries" -gt 60 ]; then
        echo "timed out waiting for /certs/tls.crt and /certs/tls.key" >&2
        exit 1
    fi
    sleep 1
done

MAIL_USERS="${MAIL_USERS:-support@example.com sales@example.com}"

for user in $MAIL_USERS; do
    home="/srv/vmail/$user"
    mkdir -p "$home/Maildir/cur" "$home/Maildir/new" "$home/Maildir/tmp"

    if [ ! -f "$home/.minicrm-seeded" ]; then
        # Drop RFC 5322 fixtures straight into the Maildir: Dovecot assigns UIDs when the
        # mailbox is first selected, so no running server or doveadm is required.
        seq=0
        for src in "/seed/$user"/*.eml; do
            [ -f "$src" ] || continue
            seq=$((seq + 1))
            cp "$src" "$home/Maildir/new/1700000000.M${seq}P1.minicrm"
        done
        touch "$home/.minicrm-seeded"
    fi

    chown -R 5000:5000 "$home"
done

exec dovecot -F
